mapper.select:
select p.*, pc.name as category_name
FROM jsh_project p
left join jsh_project_category pc on p.category_id = pc.id
where 1=1
and ifnull(p.delete_flag,'0') !='1'


    and p.name like #{bindName}


    and p.category_id = #{categoryId}


    and p.enabled = #{enabled}

order by p.id desc

mapper.update:
update jsh_project
set update_time=#{updateTime}, delete_flag='1'
where 1=1
and ifnull(delete_flag,'0') !='1'
and tenant_id = #{tenantId}
and id in (

     #{id}

 )
